create extension if not exists pgcrypto; create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,username text,avatar_url text,created_at timestamptz not null default now()); create table if not exists public.projects(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,name text not null default 'Untitled',state jsonb not null default '{}'::jsonb,version bigint not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now()); create table if not exists public.project_members(project_id uuid references public.projects(id) on delete cascade,user_id uuid references auth.users(id) on delete cascade,role text not null check(role in ('owner','editor','viewer')),created_at timestamptz not null default now(),primary key(project_id,user_id)); create table if not exists public.project_assets(id uuid primary key default gen_random_uuid(),project_id uuid references public.projects(id) on delete cascade,storage_path text not null,name text not null,mime_type text,size_bytes bigint,created_at timestamptz not null default now()); alter table public.profiles enable row level security; alter table public.projects enable row level security; alter table public.project_members enable row level security; alter table public.project_assets enable row level security; create policy "profile self" on public.profiles for all using(auth.uid()=id) with check(auth.uid()=id); create policy "project members read" on public.projects for select using(owner_id=auth.uid() or exists(select 1 from public.project_members m where m.project_id=id and m.user_id=auth.uid())); create policy "project owner write" on public.projects for all using(owner_id=auth.uid()) with check(owner_id=auth.uid()); create policy "members read" on public.project_members for select using(user_id=auth.uid() or exists(select 1 from public.projects p where p.id=project_id and p.owner_id=auth.uid())); create policy "owner manages members" on public.project_members for all using(exists(select 1 from public.projects p where p.id=project_id and p.owner_id=auth.uid())); create policy "asset members" on public.project_assets for select using(exists(select 1 from public.projects p where p.id=project_id and (p.owner_id=auth.uid() or exists(select 1 from public.project_members m where m.project_id=p.id and m.user_id=auth.uid())))); create policy "asset owner write" on public.project_assets for all using(exists(select 1 from public.projects p where p.id=project_id and p.owner_id=auth.uid())) with check(exists(select 1 from public.projects p where p.id=project_id and p.owner_id=auth.uid()));